// internal/proxy/insert.go line 180-240
func (s *insertService) Insert(ctx context.Context, req *InsertRequest) (*InsertResponse, error) {
    // Schema validation (already passed in handler)

    // Execute insert
    result, err := s.segmentWriter.Insert(ctx, req.GetData())
    if err != nil {
        return nil, status.Errorf(codes.Internal, "insert failed: %v", err)
    }

    // Build response
    resp := &InsertResponse{
        InsertCount: int64(len(result.IDs)),
        InsertIds:  result.IDs,
    }
    return resp, nil
}
